import {verifyEconomy,DEVELOPMENT_CASES} from '../scripts/commerce-expanded/harness-v2/trials.mjs';
const root='.local/inquiry-response-pilot',fixed=(await read('docs/commerce-growth/team-1/development/results.json')).selectedFixed,prior=await read('docs/commerce-growth/team-1/training/model.json');
const source='docs/commerce-expanded/harness-v2/v22-20261104/v22-20261104-case-1-team',record=await read(source+'/checkpoints.json');let model;
for(const i of [0,1]){const m=await read(source+'/review-30/fit-'+i+'/model.json');if(m.modelHash===record.schedule[0].modelHash)model=m;}
if(!model||model.ownRows!==0)throw Error('HISTORICAL_ONLY_MODEL_REQUIRED');
const historical=(await read('docs/commerce-growth/autonomy-1/funding-training/dataset.json')).rows,groups={};
for(const r of historical.filter(r=>r.kind==='ask_need')){const bucket=r.observedBucket.split('|')[2],g=groups[bucket]??={n:0,responded:0,retained:0,paymentReply:0,sharedReply:0,paymentSilent:0,sharedSilent:0};g.n++;g.responded+=r.responded;g.retained+=r.retained;const suffix=r.responded?'Reply':'Silent';g['payment'+suffix]+=r.retailNetCents;g['shared'+suffix]+=r.retailNetCents+r.merchantOrderContributionCents;}
function responseEstimates(view){
 const recent=view.outreach.history.filter(c=>c.kind==='ask_need'&&c.day<view.day&&c.day>=view.day-28),sigmoid=z=>1/(1+Math.exp(-Math.max(-30,Math.min(30,z)))),base=k=>(groups[k].responded+.5)/(groups[k].n+1),logit=p=>Math.log(p/(1-p));let shift=0;
 // Regularized scalar response calibration. Only prior-day replies enter it.
 for(let step=0;step<8;step++){let gradient=-8*shift,curvature=8;for(const c of recent){const q=sigmoid(logit(base(c.observedBucket.split('|')[2]))+shift);gradient+=Number(c.responded)-q;curvature+=q*(1-q);}shift+=gradient/curvature;}
 const orders=new Map(view.pastOrders.filter(o=>o.day<view.day).map(o=>[o.requestId,o]));return new Map(Object.entries(groups).map(([bucket,g])=>{
  let replied=0,retained=0,payment=0,shared=0;for(const c of view.outreach.history)if(c.kind==='ask_need'&&c.responded&&c.day+26<view.day&&c.observedBucket.split('|')[2]===bucket){const o=orders.get(c.requestId),yes=!!o&&!['SETTLED','PENDING_FUNDS'].includes(o.refundStatus),net=(o?(yes?o.feeCents:0)-o.processingCents:0)-c.costCents,merchant=o?o.merchants.reduce((s,m)=>s+(yes?m.grossCents-m.feeCents:0)-m.costCents-m.deliveryCents,0):0;replied++;retained+=Number(yes);payment+=net;shared+=net+merchant;}
  const q=sigmoid(logit(base(bucket))+shift),conditional=(8*(g.retained+.5)/(g.responded+1)+retained)/(8+replied),expected=(kind,observed)=>q*(8*g[kind+'Reply']/Math.max(1,g.responded)+observed)/(8+replied)+(1-q)*g[kind+'Silent']/Math.max(1,g.n-g.responded);
  return [bucket,{probability:q*conditional,expectedNetCents:expected('payment',payment),expectedSharedNetCents:expected('shared',shared),responseShift:shift}];
 }));
}
function plan(view,arm){
 if(arm==='fixed'||view.day<30)return {...outreachPlan(view,fixed.config,prior),configuration:fixed.config};
 const open=arm.endsWith('_open'),kind=open?'open_discovery':'intent_assistance',context={day:30,marketProfile:'expanded-12x600',snapshotHash:canonicalHash('DEVELOPMENT_PROBE_ONLY')},campaign={kind,objective:'joint',contactsPer100:'6',forecast:'recent14',coverDays:'7',supplierSettlement:'paypal_fast',productPreference:'lowest_acceptable_price'},contract=compileCampaign(campaign,model,fixed.config,context);
 if(arm.startsWith('classifier'))return scoreCampaign(view,{contract,model,prior});
 if(view.day>=view.marketDays)return {actions:[],configuration:fixed.config};
 const people=new Map(view.audience.map(p=>[p.customerId,p])),history=observedFeedbackHistory(view),fields=model.artifact.featureNames,estimates=new Map(),bucket=p=>{const age=p.signal?view.day-p.signal.day:99;return age<=2?'fresh':age<=7?'recent':'cold';};
 for(const [key,value]of responseEstimates(view))estimates.set(key,value);
 const limit=Math.min(6*(view.scale?.contactMultiplier||1),view.outreach.rules.dailyContactLimit-view.outreach.contactsToday,Math.floor(Math.min(view.outreach.remainingBudgetCents,view.outreach.availablePlatformCashCents)/view.outreach.rules.outreachCostCents));
 if(limit<=0)return {actions:[],configuration:fixed.config};
 const rows=contactFeatures(view,prior,7).filter(c=>{const p=people.get(c.action.customerId),age=p.signal?view.day-p.signal.day:99;if(age>7&&!(open&&c.action.kind==='ask_need'))return false;if(c.action.kind==='recommend')return c.action.catalogId===p.signal?.catalogId&&(c.features.stock>0||c.features.arrival_days<=5);return open||p.signal?.kind!=='SEARCH';}).map(c=>{const x=inputFeatures(view,c,fields,history),estimate=c.action.kind==='ask_need'?estimates.get(bucket(people.get(c.action.customerId))):predictContribution(model.artifact,model.artifact.selected,x,c.action.kind,fields),shared=c.action.kind==='ask_need'?{expectedSharedNetCents:estimate.expectedSharedNetCents}:predictSharedContribution(model.artifact,estimate.probability,x,c.action.kind,fields);if(!Number.isFinite(estimate.expectedNetCents))throw Error('INVALID_INQUIRY_ESTIMATE');return {...c,...estimate,...shared};}).filter(c=>c.expectedNetCents>0&&c.expectedSharedNetCents>c.expectedNetCents).sort((a,b)=>b.expectedSharedNetCents-a.expectedSharedNetCents||a.action.customerId.localeCompare(b.action.customerId));
 const selected=[],seen=new Set();for(const c of rows){if(seen.has(c.action.customerId))continue;seen.add(c.action.customerId);selected.push(c);if(selected.length>=limit)break;}
 return {actions:selected.map(c=>c.action),configuration:fixed.config};
}
if(!isMainThread){const allocator=openAllocator();try{const r=await runCoordinatedCase(workerData.settings,{id:workerData.arm,config:fixed.config},{allocator,prior,controller:{plan:view=>plan(view,workerData.arm)}});parentPort.postMessage({...r,arm:workerData.arm,source:'NUMERICAL_DEVELOPMENT_PROBE',modelCalls:0});}finally{allocator.close();}}
else{
 await verifyEconomy();await mkdir(root,{recursive:true});const arms=['calibrated_recent','calibrated_open'],jobs=DEVELOPMENT_CASES.flatMap(settings=>arms.map(arm=>({settings,arm}))),rows=[];
 await writeFile(root+'/protocol.json',JSON.stringify({registeredAt:new Date().toISOString(),cases:DEVELOPMENT_CASES,arms,modelHash:model.modelHash,modelOwnRows:model.ownRows,scope:'Frozen development cases only. Fit action-specific value means to completed historical rows, update a response intercept from prior-day replies, and update value only from matured outcomes. Fixed ridge/pseudo-count strength 8 is an assumption inherited from the prior estimator. Same classifier, supply configuration and contact cap. No fresh AI or confirmation claim.'},null,2));
 for(let i=0;i<jobs.length;i+=2){const batch=await Promise.all(jobs.slice(i,i+2).map(job=>new Promise((resolve,reject)=>{const w=new Worker(new URL(import.meta.url),{workerData:job});let row;w.once('message',r=>{row=r;});w.once('error',reject);w.once('exit',code=>code||!row?reject(Error('PROBE_WORKER_FAILED')):resolve(row));})));rows.push(...batch);await writeFile(root+'/rows.json',JSON.stringify(rows,null,2));for(const r of batch)console.log(JSON.stringify({regime:r.regime,arm:r.arm,paypal:r.platformUSD,merchants:r.retailerUSD,purchases:r.retainedPurchases}));}
 const controls=await read('.local/inquiry-expert-pilot/rows.json');for(const r of rows){const b=controls.find(x=>x.seed===r.seed&&x.arm==='fixed');for(const k of ['initialHash','opportunityHash','consentHash','incomeCents'])if(r[k]!==b[k])throw Error('UNMATCHED_INPUT');}
 const metrics=['platformUSD','retailerUSD','retainedPurchases','retainedVolumeUSD','terminalCashUSD','terminalInventoryUSD'],means=Object.fromEntries(arms.map(arm=>[arm,Object.fromEntries(metrics.map(k=>[k,rows.filter(r=>r.arm===arm).reduce((s,r)=>s+r[k],0)/3]))]));await verifyEconomy();await writeFile(root+'/result.json',JSON.stringify({status:'COMPLETED',means,rows,modelCalls:0,scope:'Development only; no learned team performance claim.'},null,2));console.log(JSON.stringify({means}));
